const c = require("crypto").createHash;
const EXPECTED = "62923ccda3a8bcb86b9a446feb430b7a8aa40cfd6c7b87c960a327a8b9ef72ac";
const TITLE = "Quarterly Report 2026";
const cands = [
  TITLE,
  TITLE.toLowerCase(),
  TITLE.toLowerCase().replace(/[^a-z0-9]+/g, "_"),
  TITLE.toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g,""),
  TITLE.toLowerCase().replace(/\s+/g, "_"),
  TITLE.toLowerCase().replace(/ /g, "_"),
  TITLE.replace(/\s+/g, "_"),
  "quarterly-report-2026",
  "quarterly report 2026",
  "Quarterly-Report-2026",
  "quarterly-report_2026",
  "quarterly_report_2026",
  "Quarterly_Report_2026",
  "quarterly_report_2026",
  "quarterly-report-2026",
  TITLE.toLowerCase().replace(/[^a-z0-9]+/g, "-"),
];
for (const s of cands) {
  const d = c("sha256").update(s, "utf8").digest("hex");
  if (d === EXPECTED) console.log("MATCH:", JSON.stringify(s));
}
console.log("done scanning", cands.length);
'

